/**
 * Drafts API endpoints
 */
export interface ContextFile {
    filename: string;
    content: string;
}
export interface CreateDraftRequest {
    title: string;
    prompt: string;
    deviceMode?: 'mobile' | 'tablet' | 'desktop' | 'custom';
    customWidth?: number;
    customHeight?: number;
    kind?: 'page' | 'graphic';
    contextFiles?: ContextFile[];
    /** Canvas image node ids or Brand Asset keys to send as actual visual input. */
    referenceIds?: string[];
    model?: string;
    userRequest?: string;
}
export type PresentationTransition = 'auto' | 'none' | 'fade' | 'slide' | 'push' | 'zoom' | 'reveal' | 'custom';
export interface PresentationSlideInput {
    title: string;
    prompt: string;
}
export interface CreatePresentationRequest {
    title: string;
    summary?: string;
    slides: PresentationSlideInput[];
    visualDirection: string;
    showNavigationControls: boolean;
    transition: PresentationTransition;
    customTransition?: string;
    useBrandAssets: boolean;
    contextFiles?: ContextFile[];
    referenceIds?: string[];
    model?: string;
    userRequest?: string;
}
export interface IterateDraftRequest {
    prompts?: string[];
    prompt?: string;
    count?: 1 | 2 | 3 | 4;
    mode: 'replace' | 'branch';
    contextFiles?: ContextFile[];
    /** Canvas image node ids or Brand Asset keys to send as actual visual input. */
    referenceIds?: string[];
    model?: string;
    deviceMode?: 'mobile' | 'tablet' | 'desktop' | 'custom';
    customWidth?: number;
    customHeight?: number;
    fromVersion?: number;
    userRequest?: string;
    updatedPresentationOutline?: PresentationOutlineInput;
    updatedPresentationShowNavigationControls?: boolean;
}
/**
 * A non-blocking conformance issue found in imported HTML. The message
 * includes concrete fix guidance so the authoring agent can repair and
 * re-import.
 */
export interface ImportHtmlWarning {
    code: string;
    message: string;
}
export interface AddDraftVersionRequest {
    html: string;
    title?: string;
    projectId?: string;
    generatedBy?: string;
    userRequest?: string;
    presentationOutline?: PresentationOutlineInput;
    presentationPreferences?: PresentationPreferencesInput;
}
export interface PresentationOutlineInput {
    title: string;
    summary?: string;
    slides: PresentationSlideInput[];
}
export interface PresentationPreferencesInput {
    transition: PresentationTransition;
    customTransition?: string;
    useBrandAssets: boolean;
    showNavigationControls: boolean;
}
export interface AddDraftVersionResponse {
    draftId: string;
    title: string;
    currentVersion: number;
    projectUrl: string;
    nodeUrl: string;
    previewUrl: string;
    warnings?: ImportHtmlWarning[];
}
export interface RevertDraftResponse {
    draftId: string;
    title: string;
    currentVersion: number;
    previewUrl: string;
    projectUrl: string;
    nodeUrl: string;
}
export interface PlanFlowRequest {
    flowContext?: string;
}
export interface FlowPage {
    title: string;
    prompt: string;
}
export interface ExecuteFlowRequest {
    flowContext?: string;
    pages: FlowPage[];
    contextFiles?: ContextFile[];
    /** Canvas image node ids or Brand Asset keys to send as actual visual input. */
    referenceIds?: string[];
    model?: string;
}
export interface JobCreatedResponse {
    jobId: string;
    status: 'processing';
}
/**
 * Create a draft using AI generation (async)
 */
export declare function createDraft(projectId: string, data: CreateDraftRequest): Promise<JobCreatedResponse>;
/** Create a real presentation draft from an approved outline. */
export declare function createPresentation(projectId: string, data: CreatePresentationRequest): Promise<JobCreatedResponse>;
/**
 * Iterate on a draft using AI (async)
 */
export declare function iterateDraft(draftId: string, data: IterateDraftRequest): Promise<JobCreatedResponse>;
/**
 * Push caller-authored HTML as a new version of an existing draft
 * (synchronous, no generation). The previous head is snapshotted into history
 * first, so the push is revertible.
 */
export declare function addDraftVersion(draftId: string, data: AddDraftVersionRequest): Promise<AddDraftVersionResponse>;
/**
 * Revert a draft to a prior version (synchronous, no generation)
 */
export declare function revertDraft(draftId: string, toVersion: number): Promise<RevertDraftResponse>;
/**
 * Plan flow pages using AI (async)
 */
export declare function planFlowPages(draftId: string, data: PlanFlowRequest): Promise<JobCreatedResponse>;
/**
 * Execute flow pages generation (async)
 */
export declare function executeFlowPages(draftId: string, data: ExecuteFlowRequest): Promise<JobCreatedResponse>;
